using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using MapSharedProps;using MapSharedProps.EditorTools;
// 実際に取り込んだ材質と共通 HLSL を検査する。ゲーム本体は使用しない。
public static class RootSurfaceChecks {
 [Serializable]class Fixture{public float[] samples,contexts,values,parameters,bark,actual;public int count;public string paintImageBase64;public float[] paintMap;}
 [Serializable]class Row{public string name;public bool passed;public float error;}
 [Serializable]class Report{public string status;public Row[] checks;}
 static List<Row> checks=new List<Row>();static void Check(string name,bool ok,float error=0){checks.Add(new Row{name=name,passed=ok,error=error});if(!ok)throw new Exception(name+" "+error);}
 public static void RunProbe(){var args=Environment.GetCommandLineArgs();string output=args[Array.IndexOf(args,"-nature-output")+1];int code=0;try{var export=Path.Combine(output,"new-export");Validate(MapSharedPropsBuilder.Build(export),MapSharedPropsBuilder.ReadLibrary(Path.Combine(export,"shared_props.json")),output);}catch(Exception e){code=1;Debug.LogException(e);}EditorApplication.Exit(code);}
 public static void Validate(MapSharedPropsBuilder.Result built,MapSharedPropsBuilder.LibraryDto lib,string output){
  try{Check("shared ground imported once",built.rootPaint!=null&&built.ground!=null&&built.ground.data.materialVersion==3);var ground=built.ground.material;
   foreach(var a in lib.assets)if(a.rootSurface!=null){var prefab=built.prefabs[a.id];var mesh=prefab.GetComponent<MeshFilter>().sharedMesh;var mat=prefab.GetComponent<Renderer>().sharedMaterial;var uv4=mesh.uv4;bool wood=uv4.Length==mesh.vertexCount;for(int i=0;i<uv4.Length;i++)wood&=uv4[i].y==a.rootWood[i];Check(a.id+" fixed wood/leaf mask imports",wood);Check(a.id+" one material and shared ground samplers",prefab.GetComponent<Renderer>().sharedMaterials.Length==1&&mat.IsKeywordEnabled("ROOT_SURFACE")&&mat.GetTexture("_RootGrass")==ground.GetTexture("_GroundMap")&&mat.GetTexture("_RootDirt")==ground.GetTexture("_DirtMap"));Check(a.id+" per species transition heights",Mathf.Abs(mat.GetVector("_RootSurface").x-a.rootSurface.bandMetres)<1e-6f&&Mathf.Abs(mat.GetVector("_RootSurface").y-a.rootSurface.mossHeightMetres)<1e-6f);}
   foreach(string key in new[]{"_RootGrass","_RootDirt"}){var tex=(Texture2D)built.prefabs["oak"].GetComponent<Renderer>().sharedMaterial.GetTexture(key);var imp=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(tex));Check(key+" raw gamma samples / mipmaps / trilinear",!imp.sRGBTexture&&imp.mipmapEnabled&&imp.filterMode==FilterMode.Trilinear&&imp.anisoLevel==2);}
   var fixture=JsonUtility.FromJson<Fixture>(File.ReadAllText(Path.Combine(output,"surface-browser-reference.json")));int n=fixture.count;var points=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);var contexts=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);points.filterMode=contexts.filterMode=FilterMode.Point;var pp=new Color[n];var cc=new Color[n];for(int i=0;i<n;i++){int k=i*4;pp[i]=new Color(fixture.samples[k],fixture.samples[k+1],fixture.samples[k+2],fixture.samples[k+3]);cc[i]=new Color(fixture.contexts[k],fixture.contexts[k+1],fixture.contexts[k+2],fixture.contexts[k+3]);}points.SetPixels(pp);points.Apply();contexts.SetPixels(cc);contexts.Apply();var probe=new Material(Shader.Find("Hidden/MapSharedProps/RootSurfaceProbe"));var model=built.prefabs["oak"].GetComponent<Renderer>().sharedMaterial;foreach(string key in new[]{"_RootSurface","_RootGrassParams","_RootDirtParams","_RootGrassOffset","_RootDirtOffset","_RootWaveA","_RootWaveB"})probe.SetVector(key,model.GetVector(key));probe.SetTexture("_RootGrass",model.GetTexture("_RootGrass"));probe.SetTexture("_RootDirt",model.GetTexture("_RootDirt"));probe.SetTexture("_Contexts",contexts);if(!string.IsNullOrEmpty(fixture.paintImageBase64)){var paint=new Texture2D(2,2,TextureFormat.RGBA32,false,true);paint.LoadImage(Convert.FromBase64String(fixture.paintImageBase64));paint.filterMode=FilterMode.Bilinear;paint.wrapMode=TextureWrapMode.Clamp;probe.SetTexture("_RootPaint",paint);probe.SetVector("_RootPaintMap",new Vector4(fixture.paintMap[0],fixture.paintMap[1],fixture.paintMap[2],fixture.paintMap[3]));}var rt=new RenderTexture(n,1,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();Graphics.Blit(points,rt,probe);var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);image.ReadPixels(new Rect(0,0,n,1),0,0);image.Apply();var pixels=image.GetPixels();float max=0;for(int i=0;i<n;i++)for(int j=0;j<3;j++)max=Mathf.Max(max,Mathf.Abs(pixels[i][j]-fixture.values[i*4+j]));fixture.actual=new float[n*4];for(int i=0;i<n;i++)for(int j=0;j<4;j++)fixture.actual[i*4+j]=pixels[i][j];File.WriteAllText(Path.Combine(output,"surface-unity-samples.json"),JsonUtility.ToJson(fixture));Check("60 GPU albedo samples match browser",max<.012f,max);RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(points);UnityEngine.Object.DestroyImmediate(contexts);UnityEngine.Object.DestroyImmediate(probe);
   var slope=MapSharedPropsBuilder.Build(Path.Combine(output,"slope-export"));var manager=slope.root.GetComponent<SharedPlantContact>();var actor=new GameObject("Root contact transport source").AddComponent<SharedPlantContactSource>();actor.height=1.8f;actor.radius=.3f;manager.source=actor;manager.useClock=false;int count=0;
   foreach(var e in manager.entries){var mesh=e.renderer.GetComponent<MeshFilter>().sharedMesh;var a=Array.Find(lib.assets,x=>slope.prefabs[x.id].GetComponent<MeshFilter>().sharedMesh==mesh);if(a==null||a.rootSurface==null)continue;count++;var block=new MaterialPropertyBlock();e.renderer.GetPropertyBlock(block);var surface=block.GetVector("_TDRootTerrain");Check(a.id+" terrain context transported",surface.z>.999f);var plane=block.GetVector("_TDRootSlope");actor.transform.position=e.renderer.transform.position+new Vector3(.08f,0,.1f);for(int k=0;k<180;k++)manager.Step(1/60f);e.renderer.GetPropertyBlock(block);Check(a.id+" contact preserves terrain and plane",block.GetVector("_TDRootTerrain")==surface&&block.GetVector("_TDRootSlope")==plane);actor.transform.position=new Vector3(1000,0,1000);for(int k=0;k<360;k++)manager.Step(1/60f);e.renderer.GetPropertyBlock(block);Check(a.id+" rest preserves context",e.bend==Vector2.zero&&e.velocity==Vector2.zero&&block.GetVector("_TDRootTerrain")==surface);e.renderer.transform.localScale=new Vector3(1.6f,.2f,.7f);SharedRootGrounding.SetSlope(e.renderer,new Vector2(.1f,-.04f));manager.Refresh();var b=e.renderer.localBounds;bool inside=true;for(int i=0;i<mesh.vertexCount;i++){var p=mesh.vertices[i];var wp=e.renderer.localToWorldMatrix.MultiplyPoint3x4(p);var origin=e.renderer.transform.position;wp.y+=(.1f*(wp.x-origin.x)-.04f*(wp.z-origin.z))*a.rootWeights[i];inside&=b.Contains(e.renderer.worldToLocalMatrix.MultiplyPoint3x4(wp));}Check(a.id+" non-uniform moving bounds",inside);}
   Check("24 context placements",count==24);UnityEngine.Object.DestroyImmediate(actor.gameObject);UnityEngine.Object.DestroyImmediate(slope.root);Write(output,"Passed");
  }catch{Write(output,"Failed");throw;}
 }
 static void Write(string output,string status){File.WriteAllText(Path.Combine(output,"root-surface-unity.json"),JsonUtility.ToJson(new Report{status=status,checks=checks.ToArray()},true));}
}
